@@ -0,0 +1,45 @@
+export type AdmissionBudgetContext = {
+	readonly suspended: boolean;
+	readonly used: number;
+	readonly limit: number;
+	readonly method: string;
+	readonly allowedMethods: readonly string[];
+	readonly requested: number;
+	readonly perRequestCap: number;
+};
+
+const assertCredits = (name: string, value: number): void => {
+	if (!Number.isFinite(value) || value < 0) {
+		throw new RangeError(`Expected \`${name}\` to be a finite non-negative number, got ${String(value)}`);
+	}
+};
+
+/**
+Preview how many credits a request may consume from the local quota.
+
+Returns a number of credits, not a delay.
+*/
+export default function admissionBudget(context: AdmissionBudgetContext): number {
+	const {suspended, used, limit, method, allowedMethods, requested, perRequestCap} = context;
+
+	assertCredits('used', used);
+	assertCredits('limit', limit);
+	assertCredits('requested', requested);
+	assertCredits('perRequestCap', perRequestCap);
+
+	if (suspended) {
+		return 0;
+	}
+
+	const normalizedMethod = method.toUpperCase();
+	if (!allowedMethods.some(allowedMethod => allowedMethod.toUpperCase() === normalizedMethod)) {
+		return 0;
+	}
+
+	const remaining = limit - used;
+	if (remaining <= 0) {
+		return 0;
+	}
+
+	return Math.min(remaining, requested, perRequestCap);
+}
diff --git a/test/admission-budget.ts b/test/admission-budget.ts
new file mode 100644
index 0000000..630c3f5
--- /dev/null
+++ b/test/admission-budget.ts
@@ -0,0 +1,64 @@
+import test from 'ava';
+import admissionBudget, {type AdmissionBudgetContext} from '../source/core/utils/admission-budget.js';
+
+const context: AdmissionBudgetContext = {
+	suspended: false,
+	used: 20,
+	limit: 100,
+	method: 'GET',
+	allowedMethods: ['GET', 'POST'],
+	requested: 50,
+	perRequestCap: 60,
+};
+
+test('returns the requested credits when they are the smallest bound', t => {
+	t.is(admissionBudget(context), 50);
+});
+
+test('returns the remaining quota when it is the smallest bound', t => {
+	t.is(admissionBudget({...context, used: 70}), 30);
+});
+
+test('returns the per-request cap when it is the smallest bound', t => {
+	t.is(admissionBudget({...context, perRequestCap: 10}), 10);
+});
+
+test('returns zero for suspended tenants', t => {
+	t.is(admissionBudget({...context, suspended: true}), 0);
+});
+
+test('returns zero when the quota is exhausted', t => {
+	t.is(admissionBudget({...context, used: 100}), 0);
+	t.is(admissionBudget({...context, used: 150}), 0);
+});
+
+test('returns zero for disallowed methods', t => {
+	t.is(admissionBudget({...context, method: 'DELETE'}), 0);
+	t.is(admissionBudget({...context, allowedMethods: []}), 0);
+});
+
+test('matches methods case-insensitively', t => {
+	t.is(admissionBudget({...context, method: 'get'}), 50);
+	t.is(admissionBudget({...context, allowedMethods: ['post', 'get']}), 50);
+});
+
+test('returns zero for zero requested credits or a zero cap', t => {
+	t.is(admissionBudget({...context, requested: 0}), 0);
+	t.is(admissionBudget({...context, perRequestCap: 0}), 0);
+});
+
+test('supports fractional credits', t => {
+	t.is(admissionBudget({...context, used: 99.5}), 0.5);
+});
+
+for (const key of ['used', 'limit', 'requested', 'perRequestCap'] as const) {
+	for (const value of [-1, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
+		test(`throws RangeError when \`${key}\` is ${value}`, t => {
+			t.throws(() => admissionBudget({...context, [key]: value}), {instanceOf: RangeError});
+		});
+	}
+}
+
+test('validates numeric inputs even for suspended tenants', t => {
+	t.throws(() => admissionBudget({...context, suspended: true, used: -1}), {instanceOf: RangeError});
+});
